import{_ as t,o as s,c as i,a2 as n}from"./chunks/framework.vLhlLNVn.js";const a="/assets/preset-laden.QeaNd9IF.svg",k=JSON.parse('{"title":"Effekte und Presets nutzen","description":"","frontmatter":{"order":2,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/de/02.anleitungen/02.effekte-und-presets.md"},"headers":[],"relativePath":"de/adapter/wled/anleitungen/effekte-und-presets.md","filePath":"de/adapter/wled/anleitungen/effekte-und-presets.md","lastUpdated":null}'),r={name:"de/adapter/wled/anleitungen/effekte-und-presets.md"};function d(l,e,h,c,o,u){return s(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="effekte-und-presets-nutzen" tabindex="-1">Effekte und Presets nutzen <a class="header-anchor" href="#effekte-und-presets-nutzen" aria-label="Permalink to &quot;Effekte und Presets nutzen&quot;">​</a></h1><p><a id="switch-wled-presets-via-ps"></a></p><h2 id="wie-schalte-ich-wled-presets-per-datenpunkt-ps-in-vis-blockly-oder-skript" tabindex="-1">Wie schalte ich WLED-Presets per Datenpunkt (ps) in VIS, Blockly oder Skript? <a class="header-anchor" href="#wie-schalte-ich-wled-presets-per-datenpunkt-ps-in-vis-blockly-oder-skript" aria-label="Permalink to &quot;Wie schalte ich WLED-Presets per Datenpunkt (ps) in VIS, Blockly oder Skript?&quot;">​</a></h2><p><strong>Kurz:</strong> Leg das Preset in der WLED-Oberfläche an und schreib seine Nummer als Zahl in <code>wled.0.&lt;MAC&gt;.ps</code>, und zwar als Steuerbefehl (<code>ack=false</code>). Ob das Licht dabei an- oder ausgeht, entscheidet das Preset selbst, nicht der Adapter.</p><p>Der Adapter reicht den Wert unverändert als <code>{&quot;ps&quot;:3}</code> an das Gerät weiter, per WebSocket oder HTTP. Die Presets selbst liegen nur in WLED. Der Adapter kennt ihre Nummern, aber nicht ihre Namen, und legt auch keine Liste der Presets an.</p><h3 id="welche-presets-du-brauchst" tabindex="-1">Welche Presets du brauchst <a class="header-anchor" href="#welche-presets-du-brauchst" aria-label="Permalink to &quot;Welche Presets du brauchst&quot;">​</a></h3><ol><li>Öffne die WLED-Oberfläche des Geräts im Browser und stell Farbe, Effekt und Helligkeit so ein, wie das Preset aussehen soll.</li><li>Speichere den Zustand mit „Create Preset“. Die Nummer unter „Save to ID“ ist die Zahl, die du später in <code>ps</code> schreibst. Erlaubt sind 1 bis 250.</li><li>Entscheide beim Speichern, ob „Include brightness“ an sein soll. Davon hängt ab, ob das Preset das Licht ein- oder ausschaltet (siehe unten).</li></ol><h3 id="so-setzt-du-ps" tabindex="-1">So setzt du ps <a class="header-anchor" href="#so-setzt-du-ps" aria-label="Permalink to &quot;So setzt du ps&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Wo</th><th>So geht es</th></tr></thead><tbody><tr><td>Objektbaum im Admin</td><td>Bei <code>wled.0.&lt;MAC&gt;.ps</code> die Nummer eintragen und speichern.</td></tr><tr><td>JavaScript</td><td><code>setState(&#39;wled.0.&lt;MAC&gt;.ps&#39;, 3);</code> (ohne drittes Argument ist das ein Steuerbefehl)</td></tr><tr><td>Blockly</td><td>Block „steuere“ mit dem Objekt <code>ps</code> und der Zahl als Wert. Nicht „aktualisiere“ nehmen.</td></tr><tr><td>VIS</td><td>Ein Widget, das einen festen Wert schreibt, zum Beispiel ein Knopf mit der Preset-Nummer, oder eine Auswahlliste mit den Preset-Nummern als Werten und den Namen als Texten.</td></tr></tbody></table><p>Der Adapter schickt nur Werte mit <code>ack=false</code> an das Gerät. Ein Wert mit <code>ack=true</code> („aktualisiere“ in Blockly) gilt als Rückmeldung vom Gerät und wird nicht gesendet.</p><p><code>ps</code> ist ein Datenpunkt vom Typ Zahl. Schreib deshalb <code>3</code> und nicht <code>&quot;3&quot;</code>. WLED versteht zwar auch den Text, aber ioBroker meldet dann eine Warnung zum falschen Datentyp.</p><p>Hat es geklappt, zeigt <code>ps</code> kurz darauf die Nummer, die das Gerät zurückmeldet. Hast du danach in WLED etwas von Hand verändert, meldet WLED <code>-1</code>, weil kein Preset mehr aktiv ist.</p><h3 id="warum-geht-das-licht-beim-preset-wechsel-an-oder-aus" tabindex="-1">Warum geht das Licht beim Preset-Wechsel an oder aus? <a class="header-anchor" href="#warum-geht-das-licht-beim-preset-wechsel-an-oder-aus" aria-label="Permalink to &quot;Warum geht das Licht beim Preset-Wechsel an oder aus?&quot;">​</a></h3><p>Ein Preset speichert mit „Include brightness“ auch den Ein/Aus-Zustand und die Helligkeit zum Zeitpunkt des Speicherns. Wurde es bei ausgeschaltetem Licht gespeichert, schaltet es beim Aufruf aus. Wurde es bei eingeschaltetem Licht gespeichert, schaltet es ein. Ohne „Include brightness“ bleibt das Licht so, wie es ist, also auch aus, wenn es vorher aus war.</p><p><img src="'+a+'" alt="Ablauf beim Setzen von ps: Ist die Nummer schon aktiv, passiert nichts. Sonst lädt WLED das Preset, und „Include brightness“ entscheidet über Ein/Aus und Helligkeit."></p><p>So bekommst du das gewünschte Verhalten:</p><ul><li><strong>Preset soll immer einschalten:</strong> Preset bei eingeschaltetem Licht mit „Include brightness“ neu speichern.</li><li><strong>Preset soll nur Effekt und Farbe ändern:</strong> ohne „Include brightness“ speichern und das Licht getrennt über <code>wled.0.&lt;MAC&gt;.on</code> schalten.</li><li><strong>Einschalten und Preset in einem Befehl:</strong> <code>{&quot;on&quot;:true,&quot;ps&quot;:3}</code> in den Datenpunkt <code>wled.0.&lt;MAC&gt;.action</code> schreiben. WLED wertet <code>on</code> vor <code>ps</code> aus.</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>WLED lädt ein Preset nicht noch einmal, wenn es schon das aktive Preset ist. Das gilt auch, wenn du das Licht zwischendurch über <code>on</code> ausgeschaltet hast: <code>ps</code> zeigt dann weiter dieselbe Nummer, und dieselbe Nummer noch einmal zu schreiben, bewirkt nichts. Schalte in diesem Fall mit <code>on</code> ein oder schick <code>{&quot;on&quot;:true,&quot;ps&quot;:3}</code> über <code>action</code>.</p></div><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Den aktuellen Zustand speicherst du aus ioBroker als Preset, indem du die gewünschte Nummer in <code>wled.0.&lt;MAC&gt;.psave</code> schreibst.</p></div><p><strong>Siehe auch:</strong> <a href="./skripte#switch-wled-presets-automatically-example">Presets per Bewegungsmelder schalten</a> · <a href="#step-through-presets-button-script">Nacheinander durch Presets schalten</a> · <a href="#start-wled-playlist-through-adapter">Playlist starten</a> · <a href="./../fehlerbehebung/befehle-wirken-nicht#script-not-ps-wled-ignores">Skript setzt ps oder on nicht</a> · <a href="./../fehlerbehebung/befehle-wirken-nicht#ps-jump-1-not-show">ps springt auf -1</a></p><p><a id="step-through-presets-button-script"></a></p><h2 id="wie-wechsle-ich-per-taste-oder-skript-nacheinander-durch-presets" tabindex="-1">Wie wechsle ich per Taste oder Skript nacheinander durch Presets? <a class="header-anchor" href="#wie-wechsle-ich-per-taste-oder-skript-nacheinander-durch-presets" aria-label="Permalink to &quot;Wie wechsle ich per Taste oder Skript nacheinander durch Presets?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="start-wled-playlist-through-adapter"></a></p><h2 id="wie-starte-ich-eine-wled-playlist-uber-den-adapter" tabindex="-1">Wie starte ich eine WLED-Playlist über den Adapter? <a class="header-anchor" href="#wie-starte-ich-eine-wled-playlist-uber-den-adapter" aria-label="Permalink to &quot;Wie starte ich eine WLED-Playlist über den Adapter?&quot;">​</a></h2><p><strong>Kurz:</strong> Eine Playlist ist in WLED ein Preset mit eigener Nummer. Du startest sie deshalb wie jedes Preset, indem du ihre Nummer in <code>wled.0.&lt;MAC&gt;.ps</code> schreibst. Der Datenpunkt <code>pl</code> zeigt nur an, welche Playlist gerade läuft. Ihn zu beschreiben, startet keine Playlist.</p><h3 id="playlist-uber-ps-starten" tabindex="-1">Playlist über ps starten <a class="header-anchor" href="#playlist-uber-ps-starten" aria-label="Permalink to &quot;Playlist über ps starten&quot;">​</a></h3><ol><li>Leg die Playlist in der WLED-Oberfläche an. Sie bekommt beim Speichern eine Nummer wie jedes Preset. </li><li>Schreib diese Nummer in <code>wled.0.&lt;MAC&gt;.ps</code>, zum Beispiel per JavaScript <code>setState(&#39;wled.0.&lt;MAC&gt;.ps&#39;, 9);</code> oder in Blockly mit „steuere“.</li><li>Während die Playlist läuft, zeigt <code>pl</code> ihre Nummer und <code>ps</code> das gerade aktive Preset daraus. Läuft keine Playlist, zeigt <code>pl</code> den Wert <code>-1</code>.</li></ol><p>Wie <code>ps</code> genau funktioniert, steht unter <a href="#switch-wled-presets-via-ps">Presets per Datenpunkt ps schalten</a>.</p><h3 id="playlist-ohne-gespeichertes-preset-uber-action-starten" tabindex="-1">Playlist ohne gespeichertes Preset über action starten <a class="header-anchor" href="#playlist-ohne-gespeichertes-preset-uber-action-starten" aria-label="Permalink to &quot;Playlist ohne gespeichertes Preset über action starten&quot;">​</a></h3><p>Über den Datenpunkt <code>wled.0.&lt;MAC&gt;.action</code> kannst du eine Playlist auch direkt als JSON schicken, ohne sie vorher in WLED zu speichern. Dieses Beispiel zeigt die Presets 1, 2 und 3 je 30 Sekunden lang, wiederholt das endlos und schaltet dabei ein:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;on&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;playlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ps&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;dur&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;transition&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;repeat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Schlüssel</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>ps</code></td><td>Die Preset-Nummern in der Reihenfolge, in der sie laufen sollen</td></tr><tr><td><code>dur</code></td><td>Wie lange jedes Preset bleibt, in Zehntelsekunden (<code>300</code> = 30 Sekunden)</td></tr><tr><td><code>transition</code></td><td>Überblendzeit zum nächsten Preset, in Zehntelsekunden</td></tr><tr><td><code>repeat</code></td><td>Wie oft die ganze Playlist läuft; <code>0</code> heißt endlos</td></tr><tr><td><code>end</code></td><td>Preset, das nach dem letzten Durchlauf geladen wird; wirkt nicht bei <code>repeat</code> = <code>0</code></td></tr></tbody></table><h3 id="playlist-weiterschalten-oder-beenden" tabindex="-1">Playlist weiterschalten oder beenden <a class="header-anchor" href="#playlist-weiterschalten-oder-beenden" aria-label="Permalink to &quot;Playlist weiterschalten oder beenden&quot;">​</a></h3><ul><li><strong>Zum nächsten Preset springen:</strong> <code>{&quot;np&quot;:true}</code> an <code>action</code> schicken. Das gibt es ab WLED-Firmware 0.15.</li><li><strong>Beenden:</strong> Setz ein anderes Preset über <code>ps</code> oder ändere ein Segment direkt, zum Beispiel den Effekt. Damit endet die Playlist.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Der Adapter legt <code>pl</code> als beschreibbaren Datenpunkt an. WLED wertet einen geschriebenen Wert aber nicht aus, die WLED-JSON-API führt <code>pl</code> als „read-only“. Nutze zum Starten deshalb <code>ps</code> oder <code>action</code>.</p></div><p><strong>Siehe auch:</strong> <a href="#step-through-presets-button-script">Nacheinander durch Presets schalten</a> · <a href="./befehle-an-wled#send-complete-json-command-wled">Kompletten JSON-Befehl senden</a></p><p><a id="numbers-names-effects-palettes-scripts"></a></p><h2 id="wo-finde-ich-die-nummern-und-namen-von-effekten-und-paletten-fur-skripte" tabindex="-1">Wo finde ich die Nummern und Namen von Effekten und Paletten für Skripte? <a class="header-anchor" href="#wo-finde-ich-die-nummern-und-namen-von-effekten-und-paletten-fur-skripte" aria-label="Permalink to &quot;Wo finde ich die Nummern und Namen von Effekten und Paletten für Skripte?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="control-percent-effect-show-value"></a></p><h2 id="wie-steuere-ich-den-effekt-percent-und-zeige-einen-wert-als-balken-an" tabindex="-1">Wie steuere ich den Effekt &quot;Percent&quot; und zeige einen Wert als Balken an? <a class="header-anchor" href="#wie-steuere-ich-den-effekt-percent-und-zeige-einen-wert-als-balken-an" aria-label="Permalink to &quot;Wie steuere ich den Effekt &quot;Percent&quot; und zeige einen Wert als Balken an?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="change-text-scrolling-text-effect"></a></p><h2 id="wie-andere-ich-den-text-des-effekts-scrolling-text-oder-den-segmentnamen" tabindex="-1">Wie ändere ich den Text des Effekts &quot;Scrolling Text&quot; oder den Segmentnamen? <a class="header-anchor" href="#wie-andere-ich-den-text-des-effekts-scrolling-text-oder-den-segmentnamen" aria-label="Permalink to &quot;Wie ändere ich den Text des Effekts &quot;Scrolling Text&quot; oder den Segmentnamen?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="effect-palette-survive-power-loss"></a></p><h2 id="wie-bleiben-effekt-und-palette-nach-einem-stromausfall-erhalten-und-wie-startet-wled-danach" tabindex="-1">Wie bleiben Effekt und Palette nach einem Stromausfall erhalten, und wie startet WLED danach? <a class="header-anchor" href="#wie-bleiben-effekt-und-palette-nach-einem-stromausfall-erhalten-und-wie-startet-wled-danach" aria-label="Permalink to &quot;Wie bleiben Effekt und Palette nach einem Stromausfall erhalten, und wie startet WLED danach?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p>',49)])])}const b=t(r,[["render",d]]);export{k as __pageData,b as default};
